#![cfg(feature = "mock")]
//! End-to-end test for the [`RunObserver`] observability hooks.
//!
//! A host receives live run/step records by implementing [`RunObserver`] and
//! passing it to [`run_with_observer`]. This test installs a capturing observer
//! over a multi-node flow and asserts the recorded steps (their count, node ids,
//! and per-step statuses) plus that `on_run_start` and `on_run_finish` each fire
//! exactly once, with the assembled [`Run`] reporting a completed status.
//!
//! Gated behind the `mock` feature, so plain `cargo test` skips it while
//! `cargo test --all-features` runs it.

use std::sync::{Arc, Mutex};

use serde_json::{Value, json};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run_with_observer;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};
use tinyflows::observability::{ExecutionStep, Run, RunObserver, RunStatus, StepStatus};

/// Builds a node with the given id, kind, and config.
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a trigger node with the given firing mode.
fn trigger(id: &str, kind: TriggerKind) -> Node {
    node(id, NodeKind::Trigger, json!({ "kind": kind }))
}

/// Builds an edge from `from_node`'s `main` port into `to_node`'s `main` port.
fn edge(from_node: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: "main".to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

/// What the capturing observer records across a run.
#[derive(Default)]
struct Recorded {
    run_starts: u32,
    run_finishes: u32,
    /// (node_id, was_success) per finished step, in the order received.
    steps: Vec<(String, bool)>,
    /// The terminal status carried by the assembled `Run` on finish.
    finish_status: Option<RunStatus>,
    /// The step count carried by the assembled `Run` on finish.
    finish_step_count: Option<usize>,
}

/// A [`RunObserver`] that records every hook it receives into a shared [`Recorded`].
struct Capture {
    recorded: Arc<Mutex<Recorded>>,
}

impl RunObserver for Capture {
    fn on_run_start(&self, _run_id: &str) {
        self.recorded.lock().expect("lock").run_starts += 1;
    }

    fn on_step_finish(&self, step: &ExecutionStep) {
        let success = matches!(step.status, StepStatus::Success);
        self.recorded
            .lock()
            .expect("lock")
            .steps
            .push((step.node_id.clone(), success));
    }

    fn on_run_finish(&self, run: &Run) {
        let mut recorded = self.recorded.lock().expect("lock");
        recorded.run_finishes += 1;
        recorded.finish_status = Some(run.status.clone());
        recorded.finish_step_count = Some(run.steps.len());
    }
}

/// A multi-node flow reports one `on_step_finish` per non-trigger node, fires
/// `on_run_start`/`on_run_finish` exactly once, and the assembled `Run` records a
/// completed status with a step per non-trigger node.
#[tokio::test]
async fn observer_captures_steps_and_lifecycle() {
    // trigger -> transform -> output_parser -> tool_call: three non-trigger nodes.
    let graph = WorkflowGraph {
        name: "observed".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node(
                "label",
                NodeKind::Transform,
                json!({ "set": { "seen": true } }),
            ),
            node("parse", NodeKind::OutputParser, Value::Null),
            node(
                "call",
                NodeKind::ToolCall,
                json!({ "slug": "slack.post", "args": {} }),
            ),
        ],
        edges: vec![
            edge("start", "label"),
            edge("label", "parse"),
            edge("parse", "call"),
        ],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let caps = mock_capabilities();

    let recorded = Arc::new(Mutex::new(Recorded::default()));
    let observer: Arc<dyn RunObserver> = Arc::new(Capture {
        recorded: recorded.clone(),
    });

    run_with_observer(&compiled, json!({ "x": 1 }), &caps, &observer)
        .await
        .expect("run");

    let recorded = recorded.lock().expect("lock");

    // Lifecycle hooks each fired exactly once.
    assert_eq!(recorded.run_starts, 1, "on_run_start should fire once");
    assert_eq!(recorded.run_finishes, 1, "on_run_finish should fire once");

    // One step per non-trigger node (the trigger itself does not emit a step).
    assert_eq!(
        recorded.steps.len(),
        3,
        "one step should be recorded per non-trigger node, got {:?}",
        recorded.steps
    );
    let ids: Vec<&str> = recorded.steps.iter().map(|(id, _)| id.as_str()).collect();
    assert!(
        ids.contains(&"label") && ids.contains(&"parse") && ids.contains(&"call"),
        "steps should cover every non-trigger node, got {ids:?}"
    );
    assert!(
        !ids.contains(&"start"),
        "the trigger node should not produce a step"
    );

    // Every step succeeded.
    assert!(
        recorded.steps.iter().all(|(_, success)| *success),
        "every step should have a Success status, got {:?}",
        recorded.steps
    );

    // The assembled Run handed to on_run_finish reflects a completed run.
    assert_eq!(
        recorded.finish_status,
        Some(RunStatus::Completed),
        "the finished run should report Completed status"
    );
    assert_eq!(
        recorded.finish_step_count,
        Some(3),
        "the assembled Run should carry one step per non-trigger node"
    );
}

//! Node-kind discriminators for the workflow model.

use serde::{Deserialize, Serialize};

/// The category of work a [`crate::model::Node`] performs.
///
/// Kind-specific configuration lives in [`crate::model::Node::config`] as
/// free-form JSON, validated per kind during compilation. Variants serialize as
/// `snake_case` strings on the JSON wire:
///
/// ```
/// use tinyflows::model::NodeKind;
///
/// assert_eq!(serde_json::to_string(&NodeKind::HttpRequest).unwrap(), "\"http_request\"");
/// let kind: NodeKind = serde_json::from_str("\"split_out\"").unwrap();
/// assert_eq!(kind, NodeKind::SplitOut);
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NodeKind {
    /// Entry node that starts the workflow. The trigger's firing mode is carried
    /// in config as a [`TriggerKind`].
    Trigger,
    /// Runs an LLM agent turn, with optional chat-model / memory / tool /
    /// output-parser sub-ports.
    Agent,
    /// Invokes one specific integration action (a curated Composio tool).
    ToolCall,
    /// Performs an outbound HTTP request.
    HttpRequest,
    /// Executes sandboxed user code (JavaScript or Python).
    Code,
    /// Two-way conditional branch, emitting on the `true` or `false` port.
    Condition,
    /// Multi-way branch keyed by an expression result.
    Switch,
    /// Fan-in barrier that combines multiple named inputs.
    Merge,
    /// Fan-out that emits one item per element of a list.
    SplitOut,
    /// Pure, expression-based data transform over the run state.
    Transform,
    /// Parses and validates an upstream agent's output into a structured shape.
    OutputParser,
    /// Runs another workflow as a nested sub-graph.
    SubWorkflow,
}

/// How a [`NodeKind::Trigger`] node is fired.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TriggerKind {
    /// Fired manually by the user (e.g. a "Run" button).
    Manual,
    /// Fired on a cron / interval schedule.
    Schedule,
    /// Fired by an inbound HTTP webhook.
    Webhook,
    /// Fired by a connected-app event (e.g. a Composio trigger).
    AppEvent,
    /// Fired on form submission.
    Form,
    /// Fired when invoked by another workflow.
    ExecuteByWorkflow,
    /// Fired by an inbound chat message.
    ChatMessage,
    /// Fired by an evaluation run.
    Evaluation,
    /// Fired by a system event (workflow error, file change, and similar).
    System,
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Round-trips a value through JSON and asserts the exact wire string.
    fn assert_wire<T>(value: &T, wire: &str)
    where
        T: Serialize + for<'de> Deserialize<'de> + PartialEq + std::fmt::Debug,
    {
        let json = serde_json::to_string(value).expect("serialize");
        assert_eq!(json, format!("\"{wire}\""));
        let back: T = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(&back, value);
    }

    #[test]
    fn node_kind_variants_use_snake_case() {
        assert_wire(&NodeKind::Trigger, "trigger");
        assert_wire(&NodeKind::Agent, "agent");
        assert_wire(&NodeKind::ToolCall, "tool_call");
        assert_wire(&NodeKind::HttpRequest, "http_request");
        assert_wire(&NodeKind::Code, "code");
        assert_wire(&NodeKind::Condition, "condition");
        assert_wire(&NodeKind::Switch, "switch");
        assert_wire(&NodeKind::Merge, "merge");
        assert_wire(&NodeKind::SplitOut, "split_out");
        assert_wire(&NodeKind::Transform, "transform");
        assert_wire(&NodeKind::OutputParser, "output_parser");
        assert_wire(&NodeKind::SubWorkflow, "sub_workflow");
    }

    #[test]
    fn trigger_kind_variants_use_snake_case() {
        assert_wire(&TriggerKind::Manual, "manual");
        assert_wire(&TriggerKind::Schedule, "schedule");
        assert_wire(&TriggerKind::Webhook, "webhook");
        assert_wire(&TriggerKind::AppEvent, "app_event");
        assert_wire(&TriggerKind::Form, "form");
        assert_wire(&TriggerKind::ExecuteByWorkflow, "execute_by_workflow");
        assert_wire(&TriggerKind::ChatMessage, "chat_message");
        assert_wire(&TriggerKind::Evaluation, "evaluation");
        assert_wire(&TriggerKind::System, "system");
    }

    #[test]
    fn unknown_node_kind_discriminator_is_rejected() {
        let err = serde_json::from_str::<NodeKind>("\"not_a_kind\"");
        assert!(err.is_err());
    }

    #[test]
    fn unknown_trigger_kind_discriminator_is_rejected() {
        let err = serde_json::from_str::<TriggerKind>("\"telepathy\"");
        assert!(err.is_err());
    }

    #[test]
    fn camel_case_discriminator_is_rejected() {
        // The wire format is strictly snake_case; the Rust variant name is not it.
        assert!(serde_json::from_str::<NodeKind>("\"HttpRequest\"").is_err());
        assert!(serde_json::from_str::<NodeKind>("\"splitOut\"").is_err());
    }
}

//! The tinyflows workflow definition model: a directed graph of typed nodes.
//!
//! A [`WorkflowGraph`] is the serializable source of truth for an automation.
//! Both authoring surfaces — the visual canvas and agent-first chat — produce
//! and edit the *same* `WorkflowGraph`.
//!
//! ## Versioning
//!
//! The JSON wire format is a stable contract. Two version axes make it durable
//! as the model evolves:
//!
//! - [`WorkflowGraph::schema_version`] — the overall model shape. The current
//!   value is [`CURRENT_SCHEMA_VERSION`].
//! - [`Node::type_version`] — the per-kind `config` shape for a node.
//!
//! Both fields are `#[serde(default)]`, so definitions persisted before they
//! existed still load. Load-time upgrades are performed by [`crate::migrate`].

mod node_kind;

pub use node_kind::{NodeKind, TriggerKind};

use serde::{Deserialize, Serialize};

/// The current [`WorkflowGraph`] schema version understood by this crate.
///
/// Graphs persisted with a lower `schema_version` are upgraded on load by
/// [`crate::migrate`]. Bumping this constant is a breaking JSON-format change
/// and must ship with a migration.
///
/// ```
/// assert_eq!(tinyflows::model::CURRENT_SCHEMA_VERSION, 1);
/// ```
pub const CURRENT_SCHEMA_VERSION: u32 = 1;

/// Stable identifier for a node within a [`WorkflowGraph`].
pub type NodeId = String;

/// Serde default for [`WorkflowGraph::schema_version`]: the current schema
/// version, so JSON authored before the field existed loads as up to date.
fn default_schema_version() -> u32 {
    CURRENT_SCHEMA_VERSION
}

/// Serde default for [`Node::type_version`]: the initial version (`1`) for
/// every node kind, so JSON authored before the field existed loads correctly.
fn default_type_version() -> u32 {
    1
}

/// A named input or output connection point on a [`Node`].
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Port {
    /// The port's stable name (e.g. `"main"`, `"true"`, `"false"`, `"tool"`).
    pub name: String,
    /// Optional human-readable label for the editor.
    #[serde(default)]
    pub label: Option<String>,
}

/// Optional canvas coordinates for a node (ignored by the engine).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, Default)]
pub struct Position {
    /// Horizontal position on the canvas.
    pub x: f64,
    /// Vertical position on the canvas.
    pub y: f64,
}

/// A single unit of work in a workflow.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Node {
    /// Unique id within the graph.
    pub id: NodeId,
    /// The kind of work this node performs.
    pub kind: NodeKind,
    /// Version of this node kind's `config` shape. Defaults to `1`; bumped by a
    /// kind when its configuration evolves, with a per-kind load-time migration.
    #[serde(default = "default_type_version")]
    pub type_version: u32,
    /// Human-readable name shown in the editor.
    pub name: String,
    /// Kind-specific configuration as free-form JSON.
    #[serde(default)]
    pub config: serde_json::Value,
    /// Declared output ports (for branching / multi-output nodes).
    #[serde(default)]
    pub ports: Vec<Port>,
    /// Optional canvas position.
    #[serde(default)]
    pub position: Option<Position>,
}

/// A directed connection from one node's output port to another's input port.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Edge {
    /// Source node id.
    pub from_node: NodeId,
    /// Source port name (defaults to `"main"`).
    #[serde(default = "default_port")]
    pub from_port: String,
    /// Target node id.
    pub to_node: NodeId,
    /// Target port name (defaults to `"main"`).
    #[serde(default = "default_port")]
    pub to_port: String,
}

fn default_port() -> String {
    "main".to_string()
}

/// A complete, serializable workflow definition.
///
/// A freshly [`Default`](WorkflowGraph::default)-constructed graph is stamped
/// with the [`CURRENT_SCHEMA_VERSION`], and JSON that omits the version fields
/// deserializes with the same defaults, so persisted and in-memory graphs agree:
///
/// ```
/// use tinyflows::model::{WorkflowGraph, CURRENT_SCHEMA_VERSION};
///
/// let fresh = WorkflowGraph::default();
/// assert_eq!(fresh.schema_version, CURRENT_SCHEMA_VERSION);
///
/// // JSON that predates the `schema_version` field still loads as current.
/// let loaded: WorkflowGraph =
///     serde_json::from_str(r#"{"name":"demo","nodes":[],"edges":[]}"#).unwrap();
/// assert_eq!(loaded.schema_version, CURRENT_SCHEMA_VERSION);
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WorkflowGraph {
    /// Overall model-shape version. Defaults to [`CURRENT_SCHEMA_VERSION`] so
    /// JSON authored before the field existed loads as the current shape;
    /// older persisted values are upgraded by [`crate::migrate`].
    #[serde(default = "default_schema_version")]
    pub schema_version: u32,
    /// Optional stable id of the workflow.
    #[serde(default)]
    pub id: Option<String>,
    /// Human-readable workflow name.
    #[serde(default)]
    pub name: String,
    /// The nodes in the graph.
    #[serde(default)]
    pub nodes: Vec<Node>,
    /// The directed edges connecting node ports.
    #[serde(default)]
    pub edges: Vec<Edge>,
}

impl Default for WorkflowGraph {
    /// A new, empty graph stamped with the [`CURRENT_SCHEMA_VERSION`] (rather
    /// than `0`), so freshly constructed graphs match freshly deserialized ones.
    fn default() -> Self {
        Self {
            schema_version: CURRENT_SCHEMA_VERSION,
            id: None,
            name: String::new(),
            nodes: Vec::new(),
            edges: Vec::new(),
        }
    }
}

impl WorkflowGraph {
    /// Returns the graph's trigger node, if it has exactly one.
    ///
    /// Returns `None` for a graph with zero triggers *or* more than one, so
    /// callers can treat "not exactly one trigger" uniformly.
    ///
    /// ```
    /// use tinyflows::model::WorkflowGraph;
    ///
    /// // An empty graph has no trigger.
    /// assert!(WorkflowGraph::default().trigger().is_none());
    ///
    /// // A graph deserialized with a single trigger returns it.
    /// let graph: WorkflowGraph = serde_json::from_str(
    ///     r#"{"nodes":[{"id":"t","kind":"trigger","name":"start"}],"edges":[]}"#,
    /// )
    /// .unwrap();
    /// assert_eq!(graph.trigger().map(|n| n.id.as_str()), Some("t"));
    /// ```
    #[must_use]
    pub fn trigger(&self) -> Option<&Node> {
        let mut triggers = self.nodes.iter().filter(|n| n.kind == NodeKind::Trigger);
        let first = triggers.next()?;
        match triggers.next() {
            Some(_) => None,
            None => Some(first),
        }
    }

    /// Looks up a node by id.
    #[must_use]
    pub fn node(&self, id: &str) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }

    /// Returns the ids of the **direct** successors of `start` — the target node
    /// of each edge leaving it (immediate neighbors only, not the transitive
    /// closure; ids may repeat if multiple edges connect the same pair).
    ///
    /// ```
    /// use tinyflows::model::WorkflowGraph;
    ///
    /// let graph: WorkflowGraph = serde_json::from_str(
    ///     r#"{
    ///       "nodes":[
    ///         {"id":"t","kind":"trigger","name":"start"},
    ///         {"id":"a","kind":"agent","name":"a"}
    ///       ],
    ///       "edges":[{"from_node":"t","to_node":"a"}]
    ///     }"#,
    /// )
    /// .unwrap();
    /// assert_eq!(graph.successors("t"), vec!["a"]);
    /// assert!(graph.successors("a").is_empty());
    /// ```
    #[must_use]
    pub fn successors(&self, start: &str) -> Vec<&str> {
        self.edges
            .iter()
            .filter(|e| e.from_node == start)
            .map(|e| e.to_node.as_str())
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn node(id: &str, kind: NodeKind) -> Node {
        Node {
            id: id.to_string(),
            kind,
            type_version: 1,
            name: id.to_string(),
            config: serde_json::Value::Null,
            ports: Vec::new(),
            position: None,
        }
    }

    #[test]
    fn json_round_trips() {
        let graph = WorkflowGraph {
            schema_version: CURRENT_SCHEMA_VERSION,
            id: Some("wf_1".to_string()),
            name: "demo".to_string(),
            nodes: vec![node("t", NodeKind::Trigger), node("a", NodeKind::Agent)],
            edges: vec![Edge {
                from_node: "t".to_string(),
                from_port: "main".to_string(),
                to_node: "a".to_string(),
                to_port: "main".to_string(),
            }],
        };
        let json = serde_json::to_string(&graph).expect("serialize");
        let back: WorkflowGraph = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(graph, back);
    }

    #[test]
    fn edge_ports_default_to_main() {
        let json = r#"{"from_node":"t","to_node":"a"}"#;
        let edge: Edge = serde_json::from_str(json).expect("deserialize");
        assert_eq!(edge.from_port, "main");
        assert_eq!(edge.to_port, "main");
    }

    #[test]
    fn trigger_and_lookup() {
        let graph = WorkflowGraph {
            nodes: vec![node("t", NodeKind::Trigger), node("a", NodeKind::Agent)],
            ..Default::default()
        };
        assert_eq!(graph.trigger().map(|n| n.id.as_str()), Some("t"));
        assert_eq!(graph.node("a").map(|n| n.id.as_str()), Some("a"));
        assert!(graph.node("missing").is_none());
    }

    #[test]
    fn default_stamps_current_schema_version() {
        let graph = WorkflowGraph::default();
        assert_eq!(graph.schema_version, CURRENT_SCHEMA_VERSION);
        assert_eq!(graph.schema_version, 1);
        assert!(graph.id.is_none());
        assert_eq!(graph.name, "");
        assert!(graph.nodes.is_empty());
        assert!(graph.edges.is_empty());
    }

    #[test]
    fn trigger_returns_none_with_zero_triggers() {
        let graph = WorkflowGraph {
            nodes: vec![node("a", NodeKind::Agent)],
            ..Default::default()
        };
        assert!(graph.trigger().is_none());
    }

    #[test]
    fn trigger_returns_none_with_multiple_triggers() {
        let graph = WorkflowGraph {
            nodes: vec![node("t1", NodeKind::Trigger), node("t2", NodeKind::Trigger)],
            ..Default::default()
        };
        assert!(graph.trigger().is_none());
    }

    #[test]
    fn trigger_returns_the_single_trigger() {
        let graph = WorkflowGraph {
            nodes: vec![node("a", NodeKind::Agent), node("t", NodeKind::Trigger)],
            ..Default::default()
        };
        assert_eq!(graph.trigger().map(|n| n.id.as_str()), Some("t"));
    }

    #[test]
    fn successors_lists_direct_edge_targets() {
        let graph = WorkflowGraph {
            nodes: vec![
                node("t", NodeKind::Trigger),
                node("a", NodeKind::Agent),
                node("b", NodeKind::Agent),
            ],
            edges: vec![
                Edge {
                    from_node: "t".to_string(),
                    from_port: "main".to_string(),
                    to_node: "a".to_string(),
                    to_port: "main".to_string(),
                },
                Edge {
                    from_node: "t".to_string(),
                    from_port: "main".to_string(),
                    to_node: "b".to_string(),
                    to_port: "main".to_string(),
                },
            ],
            ..Default::default()
        };
        assert_eq!(graph.successors("t"), vec!["a", "b"]);
        assert!(graph.successors("a").is_empty());
        assert!(graph.successors("missing").is_empty());
    }

    #[test]
    fn successors_may_repeat_for_parallel_edges() {
        let graph = WorkflowGraph {
            nodes: vec![node("t", NodeKind::Trigger), node("a", NodeKind::Agent)],
            edges: vec![
                Edge {
                    from_node: "t".to_string(),
                    from_port: "main".to_string(),
                    to_node: "a".to_string(),
                    to_port: "main".to_string(),
                },
                Edge {
                    from_node: "t".to_string(),
                    from_port: "other".to_string(),
                    to_node: "a".to_string(),
                    to_port: "main".to_string(),
                },
            ],
            ..Default::default()
        };
        assert_eq!(graph.successors("t"), vec!["a", "a"]);
    }

    #[test]
    fn round_trip_preserves_version_fields() {
        let graph = WorkflowGraph {
            schema_version: CURRENT_SCHEMA_VERSION,
            id: Some("wf_1".to_string()),
            name: "demo".to_string(),
            nodes: vec![Node {
                id: "t".to_string(),
                kind: NodeKind::Trigger,
                type_version: 3,
                name: "t".to_string(),
                config: serde_json::json!({"mode": "manual"}),
                ports: Vec::new(),
                position: None,
            }],
            edges: Vec::new(),
        };
        let json = serde_json::to_string(&graph).expect("serialize");
        assert!(json.contains("\"schema_version\":1"));
        assert!(json.contains("\"type_version\":3"));
        let back: WorkflowGraph = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(graph, back);
        assert_eq!(back.nodes[0].type_version, 3);
    }

    #[test]
    fn omitted_version_fields_use_serde_defaults() {
        // A graph and node authored before the version fields existed.
        let json = r#"{
            "name": "legacy",
            "nodes": [{"id": "t", "kind": "trigger", "name": "start"}],
            "edges": []
        }"#;
        let graph: WorkflowGraph = serde_json::from_str(json).expect("deserialize");
        assert_eq!(graph.schema_version, CURRENT_SCHEMA_VERSION);
        assert_eq!(graph.nodes[0].type_version, default_type_version());
        assert_eq!(graph.nodes[0].type_version, 1);
        // Other `#[serde(default)]` fields fill in too.
        assert!(graph.id.is_none());
        assert!(graph.nodes[0].config.is_null());
        assert!(graph.nodes[0].ports.is_empty());
        assert!(graph.nodes[0].position.is_none());
    }

    #[test]
    fn edge_from_port_defaults_to_main() {
        let json = r#"{"from_node":"t","to_node":"a","to_port":"custom"}"#;
        let edge: Edge = serde_json::from_str(json).expect("deserialize");
        assert_eq!(edge.from_port, "main");
        assert_eq!(edge.to_port, "custom");
    }
}

//! The `agent` node: an LLM agent turn.

use async_trait::async_trait;

use crate::data::Item;
use crate::error::Result;
use crate::nodes::{NodeContext, NodeExecutor, NodeOutput};

/// Runs an LLM agent turn with optional chat-model / memory / tool /
/// output-parser sub-ports (via [`crate::caps::LlmProvider`] and
/// [`crate::caps::ToolInvoker`]).
#[derive(Debug, Default, Clone)]
pub struct AgentNode;

#[async_trait]
impl NodeExecutor for AgentNode {
    async fn execute(&self, ctx: NodeContext<'_>) -> Result<NodeOutput> {
        // Data-binding: resolve any `=`-expressions in the config against the
        // node's input before treating the config as the completion request.
        let scope = crate::nodes::expr_scope(&ctx);
        let cfg = crate::expr::resolve(&ctx.node.config, &scope);
        // A3-basic: the node config is the completion request; sub-port wiring is a later refinement.
        let conn = cfg
            .get("connection_ref")
            .and_then(serde_json::Value::as_str);
        let response = ctx.caps.llm.complete(cfg.clone(), conn).await?;
        Ok(NodeOutput::main(vec![Item::new(response)]))
    }
}

