//! Run/step observability records and the host-facing [`RunObserver`] hook.
//!
//! tinyflows **emits** structured records of what happened during a run; the
//! host **persists** and renders them — the crate never owns a database.
//! A [`Run`] captures one workflow
//! execution as a sequence of [`ExecutionStep`]s, one per non-trigger node
//! activation, each recording the node's status, output items, and wall-clock
//! duration.
//!
//! A host receives these live by implementing [`RunObserver`] and passing it to
//! [`crate::engine::run_with_observer`]. Every callback has a default no-op body,
//! so a host implements only the hooks it cares about. The default
//! [`crate::engine::run`] path installs a [`NoopObserver`], so observability adds
//! no cost unless a host opts in.
//!
//! ```
//! use std::sync::{Arc, Mutex};
//! use tinyflows::observability::{ExecutionStep, Run, RunObserver, StepStatus};
//!
//! #[derive(Default)]
//! struct Recorder {
//!     nodes: Mutex<Vec<String>>,
//! }
//!
//! impl RunObserver for Recorder {
//!     fn on_step_finish(&self, step: &ExecutionStep) {
//!         self.nodes.lock().unwrap().push(step.node_id.clone());
//!     }
//! }
//!
//! let recorder = Recorder::default();
//! recorder.on_step_finish(&ExecutionStep {
//!     node_id: "parse".to_string(),
//!     status: StepStatus::Success,
//!     output: serde_json::json!([]),
//!     duration_ms: 0,
//! });
//! assert_eq!(recorder.nodes.lock().unwrap().as_slice(), ["parse"]);
//! ```

use serde_json::Value;

/// The lifecycle status of a whole [`Run`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RunStatus {
    /// The run is still executing (not yet driven to completion).
    Running,
    /// The run reached a terminal node and completed successfully.
    Completed,
    /// The run ended because a node failed under a `stop` error policy.
    Failed,
}

/// The outcome of a single [`ExecutionStep`].
#[derive(Debug, Clone)]
pub enum StepStatus {
    /// The node executed and produced output items.
    Success,
    /// The node's executor errored (after any retries were exhausted).
    Error,
}

/// One node activation within a [`Run`]: what the node produced, whether it
/// succeeded, and how long it took.
///
/// This is the record the canvas renders when a user inspects a node, and what a
/// run-history view summarizes.
#[derive(Debug, Clone)]
pub struct ExecutionStep {
    /// The id of the node this step ran.
    pub node_id: String,
    /// Whether the node succeeded or errored.
    pub status: StepStatus,
    /// The items the node emitted as a JSON value, or [`Value::Null`] on error.
    pub output: Value,
    /// Wall-clock duration of the node's executor, in milliseconds.
    pub duration_ms: u128,
}

/// One execution of a workflow, captured as an ordered list of [`ExecutionStep`]s.
///
/// The engine emits steps live via [`RunObserver::on_step_finish`] and hands the
/// assembled `Run` to [`RunObserver::on_run_finish`] once the run settles.
#[derive(Debug, Clone)]
pub struct Run {
    /// Unique id for this run (process-local, e.g. `"run-3"`).
    pub id: String,
    /// The run's terminal status.
    pub status: RunStatus,
    /// The per-node steps, in the order they finished.
    pub steps: Vec<ExecutionStep>,
}

/// A host-implemented hook that receives run/step records as a run executes.
///
/// Every method has a default no-op body, so a host overrides only the callbacks
/// it needs. Implementations must be `Send + Sync`: the engine clones the
/// observer (as `Arc<dyn RunObserver>`) into each node handler, which run across
/// threads. Hosts may apply redaction here before persisting or logging.
pub trait RunObserver: Send + Sync {
    /// Called once, before any node runs, with the new run's id.
    fn on_run_start(&self, run_id: &str) {
        let _ = run_id;
    }

    /// Called once per non-trigger node activation, as each step finishes.
    fn on_step_finish(&self, step: &ExecutionStep) {
        let _ = step;
    }

    /// Called once, after the run settles, with the assembled [`Run`] record.
    fn on_run_finish(&self, run: &Run) {
        let _ = run;
    }
}

/// A [`RunObserver`] that ignores every callback.
///
/// Installed by [`crate::engine::run`] so the default run path carries no
/// observability overhead.
pub struct NoopObserver;

impl RunObserver for NoopObserver {}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};

    #[test]
    fn noop_observer_callbacks_are_inert() {
        let observer = NoopObserver;
        observer.on_run_start("run-0");
        observer.on_step_finish(&ExecutionStep {
            node_id: "n".to_string(),
            status: StepStatus::Success,
            output: Value::Null,
            duration_ms: 0,
        });
        observer.on_run_finish(&Run {
            id: "run-0".to_string(),
            status: RunStatus::Completed,
            steps: Vec::new(),
        });
    }

    #[test]
    fn run_status_equality() {
        assert_eq!(RunStatus::Completed, RunStatus::Completed);
        assert_ne!(RunStatus::Completed, RunStatus::Failed);
    }

    #[test]
    fn run_status_variants_are_distinct() {
        assert_ne!(RunStatus::Running, RunStatus::Completed);
        assert_ne!(RunStatus::Running, RunStatus::Failed);
        assert_ne!(RunStatus::Completed, RunStatus::Failed);
    }

    #[test]
    fn constructs_execution_step_with_each_status() {
        // `StepStatus` does not derive `PartialEq`, so match to inspect it.
        let ok = ExecutionStep {
            node_id: "parse".to_string(),
            status: StepStatus::Success,
            output: serde_json::json!([{ "json": { "x": 1 } }]),
            duration_ms: 12,
        };
        assert_eq!(ok.node_id, "parse");
        assert_eq!(ok.duration_ms, 12);
        assert!(matches!(ok.status, StepStatus::Success));
        assert_eq!(ok.output, serde_json::json!([{ "json": { "x": 1 } }]));

        let err = ExecutionStep {
            node_id: "http".to_string(),
            status: StepStatus::Error,
            output: Value::Null,
            duration_ms: 0,
        };
        assert!(matches!(err.status, StepStatus::Error));
        assert_eq!(err.output, Value::Null);
    }

    #[test]
    fn constructs_run_with_steps() {
        let run = Run {
            id: "run-7".to_string(),
            status: RunStatus::Completed,
            steps: vec![ExecutionStep {
                node_id: "a".to_string(),
                status: StepStatus::Success,
                output: serde_json::json!([]),
                duration_ms: 3,
            }],
        };
        assert_eq!(run.id, "run-7");
        assert_eq!(run.status, RunStatus::Completed);
        assert_eq!(run.steps.len(), 1);
        assert_eq!(run.steps[0].node_id, "a");
    }

    #[test]
    fn cloned_run_is_independent() {
        let run = Run {
            id: "run-1".to_string(),
            status: RunStatus::Running,
            steps: Vec::new(),
        };
        let clone = run.clone();
        assert_eq!(clone.id, run.id);
        assert_eq!(clone.status, run.status);
    }

    /// A capturing observer used to assert the callbacks fire with the right
    /// records.
    #[derive(Default)]
    struct Capture {
        started: Mutex<Vec<String>>,
        steps: Mutex<Vec<String>>,
        finished: Mutex<Vec<(String, RunStatus)>>,
    }

    impl RunObserver for Capture {
        fn on_run_start(&self, run_id: &str) {
            self.started.lock().unwrap().push(run_id.to_string());
        }

        fn on_step_finish(&self, step: &ExecutionStep) {
            self.steps.lock().unwrap().push(step.node_id.clone());
        }

        fn on_run_finish(&self, run: &Run) {
            self.finished
                .lock()
                .unwrap()
                .push((run.id.clone(), run.status.clone()));
        }
    }

    #[test]
    fn custom_observer_receives_all_callbacks() {
        let observer = Capture::default();

        observer.on_run_start("run-9");
        observer.on_step_finish(&ExecutionStep {
            node_id: "first".to_string(),
            status: StepStatus::Success,
            output: serde_json::json!([]),
            duration_ms: 1,
        });
        observer.on_step_finish(&ExecutionStep {
            node_id: "second".to_string(),
            status: StepStatus::Error,
            output: Value::Null,
            duration_ms: 2,
        });
        observer.on_run_finish(&Run {
            id: "run-9".to_string(),
            status: RunStatus::Failed,
            steps: Vec::new(),
        });

        assert_eq!(observer.started.lock().unwrap().as_slice(), ["run-9"]);
        assert_eq!(
            observer.steps.lock().unwrap().as_slice(),
            ["first", "second"]
        );
        assert_eq!(
            observer.finished.lock().unwrap().as_slice(),
            [("run-9".to_string(), RunStatus::Failed)]
        );
    }

    #[test]
    fn observer_is_usable_as_trait_object() {
        // The engine holds the observer as `Arc<dyn RunObserver>`; confirm a
        // custom impl coerces and dispatches dynamically.
        let observer: Arc<dyn RunObserver> = Arc::new(Capture::default());
        observer.on_run_start("run-dyn");
        observer.on_step_finish(&ExecutionStep {
            node_id: "n".to_string(),
            status: StepStatus::Success,
            output: serde_json::json!([]),
            duration_ms: 0,
        });
    }
}

#![cfg(feature = "mock")]
//! End-to-end integration tests for conditional routing.
//!
//! These build real [`WorkflowGraph`]s, compile them, and drive them against the
//! deterministic [mock capabilities](tinyflows::caps::mock), asserting that
//! `condition` and `switch` nodes send data down *only* the branch(es) their
//! routing decision selects — and that non-selected branch nodes never execute
//! (their run-state slot stays `null`).
//!
//! Data-flow reminder (see `src/engine.rs`): the trigger's items slot is seeded
//! with a single item carrying the run input, so a branching node placed directly
//! after the trigger reads its routing field off that input item. A `condition`
//! and `switch` pass their input through unchanged on the chosen port.
//!
//! Gated behind the `mock` cargo feature, so plain `cargo test` skips it while
//! `cargo test --all-features` runs it.

use serde_json::{Value, json};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config (no ports, no position).
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a manual trigger node.
fn trigger(id: &str) -> Node {
    node(
        id,
        NodeKind::Trigger,
        json!({ "kind": TriggerKind::Manual }),
    )
}

/// Builds an edge from `from_node`'s `from_port` into `to_node`'s `"main"` port.
fn edge(from_node: &str, from_port: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: from_port.to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

/// A two-way `condition` on the trigger's input field `go`:
/// `trigger -> condition(field=go) -> {true -> yes | false -> no}`. Both leaves
/// are `tool_call`s that echo a distinct slug, so we can tell which branch ran.
fn condition_graph() -> WorkflowGraph {
    WorkflowGraph {
        name: "condition_branch".to_string(),
        nodes: vec![
            trigger("start"),
            node("branch", NodeKind::Condition, json!({ "field": "go" })),
            node(
                "yes",
                NodeKind::ToolCall,
                json!({ "slug": "slack.notify", "args": { "path": "true" } }),
            ),
            node(
                "no",
                NodeKind::ToolCall,
                json!({ "slug": "slack.skip", "args": { "path": "false" } }),
            ),
        ],
        edges: vec![
            edge("start", "main", "branch"),
            edge("branch", "true", "yes"),
            edge("branch", "false", "no"),
        ],
        ..Default::default()
    }
}

#[tokio::test]
async fn condition_routes_truthy_input_to_true_branch() {
    let compiled = compile(&condition_graph()).expect("compile");
    let outcome = run(&compiled, json!({ "go": true }), &mock_capabilities())
        .await
        .expect("run");
    let out = &outcome.output;

    // Only the `true` branch ran and echoed its slug.
    assert_eq!(
        out["nodes"]["yes"]["items"][0]["json"]["tool"],
        "slack.notify"
    );
    // The `false` branch never executed, so it has no slot in the run state.
    assert!(
        out["nodes"]["no"].is_null(),
        "the false branch must not run for truthy input"
    );
}

#[tokio::test]
async fn condition_routes_falsey_input_to_false_branch() {
    let compiled = compile(&condition_graph()).expect("compile");
    let outcome = run(&compiled, json!({ "go": false }), &mock_capabilities())
        .await
        .expect("run");
    let out = &outcome.output;

    // Only the `false` branch ran.
    assert_eq!(out["nodes"]["no"]["items"][0]["json"]["tool"], "slack.skip");
    // The `true` branch never executed.
    assert!(
        out["nodes"]["yes"].is_null(),
        "the true branch must not run for falsey input"
    );
}

/// A `switch` keyed on the input field `kind` with three explicit case ports
/// (`a`, `b`, `c`) plus a `default` port. Each leaf echoes a distinct slug.
fn switch_graph() -> WorkflowGraph {
    WorkflowGraph {
        name: "switch_branch".to_string(),
        nodes: vec![
            trigger("start"),
            node("route", NodeKind::Switch, json!({ "field": "kind" })),
            node("leaf_a", NodeKind::ToolCall, json!({ "slug": "case.a" })),
            node("leaf_b", NodeKind::ToolCall, json!({ "slug": "case.b" })),
            node("leaf_c", NodeKind::ToolCall, json!({ "slug": "case.c" })),
            node(
                "leaf_default",
                NodeKind::ToolCall,
                json!({ "slug": "case.default" }),
            ),
        ],
        edges: vec![
            edge("start", "main", "route"),
            edge("route", "a", "leaf_a"),
            edge("route", "b", "leaf_b"),
            edge("route", "c", "leaf_c"),
            edge("route", "default", "leaf_default"),
        ],
        ..Default::default()
    }
}

#[tokio::test]
async fn switch_routes_each_of_three_cases() {
    // Run the same graph once per case value and assert exactly that leaf ran.
    for (kind, ran, slug) in [
        ("a", "leaf_a", "case.a"),
        ("b", "leaf_b", "case.b"),
        ("c", "leaf_c", "case.c"),
    ] {
        let compiled = compile(&switch_graph()).expect("compile");
        let outcome = run(&compiled, json!({ "kind": kind }), &mock_capabilities())
            .await
            .expect("run");
        let out = &outcome.output;

        assert_eq!(
            out["nodes"][ran]["items"][0]["json"]["tool"], slug,
            "case {kind} should route to {ran}"
        );
        // Every other leaf, including default, must be untouched.
        for other in ["leaf_a", "leaf_b", "leaf_c", "leaf_default"] {
            if other != ran {
                assert!(
                    out["nodes"][other].is_null(),
                    "case {kind}: {other} must not run"
                );
            }
        }
    }
}

#[tokio::test]
async fn switch_routes_no_match_to_default() {
    // No `kind` field at all: the switch's key resolves to null, which routes to
    // the `default` port.
    let compiled = compile(&switch_graph()).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "other": "unknown" }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    assert_eq!(
        out["nodes"]["leaf_default"]["items"][0]["json"]["tool"],
        "case.default"
    );
    for other in ["leaf_a", "leaf_b", "leaf_c"] {
        assert!(
            out["nodes"][other].is_null(),
            "no-match run: {other} must not run"
        );
    }
}

/// A two-level nested branch:
/// `trigger -> outer(condition=outer) ->`
///   `true  -> inner(condition=inner) -> {true -> tt | false -> tf}`
///   `false -> ff`.
/// The inner condition reads its field off the item the outer condition passed
/// through, so nesting composes.
fn nested_graph() -> WorkflowGraph {
    WorkflowGraph {
        name: "nested_branch".to_string(),
        nodes: vec![
            trigger("start"),
            node("outer", NodeKind::Condition, json!({ "field": "outer" })),
            node("inner", NodeKind::Condition, json!({ "field": "inner" })),
            node("tt", NodeKind::ToolCall, json!({ "slug": "leaf.tt" })),
            node("tf", NodeKind::ToolCall, json!({ "slug": "leaf.tf" })),
            node("ff", NodeKind::ToolCall, json!({ "slug": "leaf.ff" })),
        ],
        edges: vec![
            edge("start", "main", "outer"),
            edge("outer", "true", "inner"),
            edge("outer", "false", "ff"),
            edge("inner", "true", "tt"),
            edge("inner", "false", "tf"),
        ],
        ..Default::default()
    }
}

#[tokio::test]
async fn nested_branch_reaches_inner_true_leaf() {
    let compiled = compile(&nested_graph()).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "outer": true, "inner": true }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    assert_eq!(out["nodes"]["tt"]["items"][0]["json"]["tool"], "leaf.tt");
    assert!(out["nodes"]["tf"].is_null(), "tf must not run");
    assert!(out["nodes"]["ff"].is_null(), "ff must not run");
}

#[tokio::test]
async fn nested_branch_reaches_inner_false_leaf() {
    let compiled = compile(&nested_graph()).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "outer": true, "inner": false }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    assert_eq!(out["nodes"]["tf"]["items"][0]["json"]["tool"], "leaf.tf");
    assert!(out["nodes"]["tt"].is_null(), "tt must not run");
    assert!(out["nodes"]["ff"].is_null(), "ff must not run");
}

