/// One big workflow chaining many kinds together end to end:
/// `trigger -> http_request -> code -> split_out -> transform -> condition
/// -> {true: tool_call, false: output_parser}`, with the `true` branch feeding a
/// `merge` and then a final `agent`. Proves a heterogeneous pipeline drives to
/// completion with data flowing through.
#[tokio::test]
async fn big_chained_workflow_runs_end_to_end() {
    let graph = WorkflowGraph {
        name: "big_chain".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node(
                "fetch",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://api.example/items" }),
            ),
            node(
                "process",
                NodeKind::Code,
                json!({ "language": "python", "source": "transform(items)" }),
            ),
            // The code mock wraps its input under `result` (an array), so splitting
            // on that path fans it back out into per-element items.
            node("fan", NodeKind::SplitOut, json!({ "path": "result" })),
            node(
                "label",
                NodeKind::Transform,
                json!({ "set": { "stage": "labeled", "ok": true } }),
            ),
            node("check", NodeKind::Condition, json!({ "field": "ok" })),
            node(
                "notify",
                NodeKind::ToolCall,
                json!({ "slug": "slack.post", "args": { "channel": "ops" } }),
            ),
            node("skipped", NodeKind::OutputParser, Value::Null),
            node("gather", NodeKind::Merge, Value::Null),
            node(
                "summarize",
                NodeKind::Agent,
                json!({ "prompt": "Summarize the run" }),
            ),
        ],
        edges: vec![
            edge("start", "main", "fetch"),
            edge("fetch", "main", "process"),
            edge("process", "main", "fan"),
            edge("fan", "main", "label"),
            edge("label", "main", "check"),
            edge("check", "true", "notify"),
            edge("check", "false", "skipped"),
            edge("notify", "main", "gather"),
            edge("gather", "main", "summarize"),
        ],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "query": "recent" }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    // HTTP hop echoed the canned 200 response.
    assert_eq!(out["nodes"]["fetch"]["items"][0]["json"]["status"], 200);
    // split_out fanned the code node's `result` array into >= 1 item.
    assert!(
        !out["nodes"]["fan"]["items"]
            .as_array()
            .expect("split_out items")
            .is_empty(),
        "split_out should emit at least one item"
    );
    // The transform stamped its fields onto the fanned items.
    assert_eq!(
        out["nodes"]["label"]["items"][0]["json"]["stage"],
        json!("labeled")
    );
    // The condition took the `true` branch, so the tool_call ran and the `false`
    // branch's output_parser did not.
    assert_eq!(
        out["nodes"]["notify"]["items"][0]["json"]["tool"],
        json!("slack.post")
    );
    assert!(
        out["nodes"]["skipped"].is_null(),
        "the false branch should not have run"
    );
    // The merge barrier and the terminal agent both ran.
    assert!(
        !out["nodes"]["gather"]["items"].is_null(),
        "the merge should have run"
    );
    assert_eq!(
        out["nodes"]["summarize"]["items"][0]["json"]["completion"]["prompt"],
        json!("Summarize the run"),
        "the terminal agent should have completed its config request"
    );
    assert!(outcome.pending_approvals.is_empty());
}

#![cfg(feature = "mock")]
//! Reliability end-to-end tests that exercise real engine execution paths using
//! *custom* host-capability implementations swapped into the otherwise-mock
//! [`Capabilities`](tinyflows::caps::Capabilities) bundle.
//!
//! Unlike `tests/reference_workflows.rs`, which drives the deterministic mock
//! capabilities, these tests replace exactly one capability slot with a bespoke
//! `Arc<dyn ...>` impl to observe engine behavior that the mocks can't provoke:
//!
//! 1. the retry loop recovering after transient failures (`FlakyTool`),
//! 2. a per-node timeout firing on a slow capability (`SlowCode`), and
//! 3. the recursion limit bounding a genuinely cyclic graph.
//!
//! Gated behind the `mock` cargo feature so `cargo test` (no features) skips it
//! while `cargo test --all-features` runs it. Every scenario uses tiny
//! timeouts/limits so the suite can never hang.

use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::Duration;

use async_trait::async_trait;
use serde_json::{Value, json};

use tinyflows::caps::mock::mock_capabilities;
use tinyflows::caps::{CodeLanguage, CodeRunner, ToolInvoker};
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::error::{EngineError, Result as CapResult};
use tinyflows::model::{Edge, Node, NodeKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config (no ports, no position).
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a `main` -> `main` edge from `from` to `to`.
fn edge(from: &str, to: &str) -> Edge {
    Edge {
        from_node: from.to_string(),
        from_port: "main".to_string(),
        to_node: to.to_string(),
        to_port: "main".to_string(),
    }
}

/// A [`ToolInvoker`] whose first two invocations fail and every invocation after
/// that succeeds — used to prove the engine's retry loop recovers on a later
/// attempt (the "first `Ok` breaks the loop" branch).
struct FlakyTool {
    /// Number of times [`FlakyTool::invoke`] has been entered.
    calls: AtomicUsize,
}

#[async_trait]
impl ToolInvoker for FlakyTool {
    async fn invoke(&self, _slug: &str, _args: Value, _conn: Option<&str>) -> CapResult<Value> {
        // 0-based index of this attempt. Attempts 0 and 1 fail; attempt 2+ succeed.
        let attempt = self.calls.fetch_add(1, Ordering::SeqCst);
        if attempt < 2 {
            Err(EngineError::Capability(format!(
                "flaky transient failure on attempt {}",
                attempt + 1
            )))
        } else {
            Ok(json!({ "ok": true }))
        }
    }
}

#[tokio::test]
async fn retry_recovers_after_transient_failures() {
    // trigger -> call(tool_call){ retry: max_attempts=3 }. The FlakyTool fails the
    // first two invocations and succeeds on the third; the retry loop must use that
    // success, so the node's output item is the SUCCESS payload (not an error item).
    let flaky = Arc::new(FlakyTool {
        calls: AtomicUsize::new(0),
    });
    let mut caps = mock_capabilities();
    caps.tools = flaky.clone();

    let graph = WorkflowGraph {
        name: "retry_recovers".to_string(),
        nodes: vec![
            node("t", NodeKind::Trigger, Value::Null),
            node(
                "call",
                NodeKind::ToolCall,
                json!({ "slug": "x", "retry": { "max_attempts": 3 } }),
            ),
        ],
        edges: vec![edge("t", "call")],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({}), &caps)
        .await
        .expect("run should recover once the tool succeeds on attempt 3");

    let item = &outcome.output["nodes"]["call"]["items"][0]["json"];
    assert_eq!(
        item,
        &json!({ "ok": true }),
        "the recovered success payload should be the node's output item"
    );
    assert!(
        item.get("error").is_none(),
        "a recovered node must not emit an error item, got: {item}"
    );
    assert_eq!(
        flaky.calls.load(Ordering::SeqCst),
        3,
        "the tool should be invoked exactly three times (fail, fail, succeed)"
    );
}

/// A [`CodeRunner`] that sleeps well past a one-second node timeout before it
/// would return — used to prove a per-node timeout aborts the node.
struct SlowCode;

#[async_trait]
impl CodeRunner for SlowCode {
    async fn run(&self, _language: CodeLanguage, _source: &str, _input: Value) -> CapResult<Value> {
        tokio::time::sleep(Duration::from_millis(1500)).await;
        Ok(json!({ "done": true }))
    }
}

#[tokio::test]
async fn node_timeout_fires_on_a_slow_capability() {
    // trigger{node_timeout_secs=1} -> slow(code). The SlowCode node awaits 1.5s,
    // exceeding the 1s per-node timeout, so the run must error rather than complete.
    let mut caps = mock_capabilities();
    caps.code = Arc::new(SlowCode);

    let graph = WorkflowGraph {
        name: "node_timeout".to_string(),
        nodes: vec![
            node("t", NodeKind::Trigger, json!({ "node_timeout_secs": 1 })),
            node("slow", NodeKind::Code, json!({})),
        ],
        edges: vec![edge("t", "slow")],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let result = run(&compiled, json!({}), &caps).await;

    assert!(
        result.is_err(),
        "the node should exceed its 1s timeout and fail the run, got: {result:?}"
    );
}

#[tokio::test]
async fn recursion_limit_bounds_a_cycle() {
    // A genuinely cyclic graph: trigger -> a -> b -> trigger (the b->t edge closes
    // the loop). With a small recursion_limit the run must terminate with an error
    // instead of looping forever. A 10s outer guard ensures the test itself can
    // never hang the suite even if the limit were not enforced.
    //
    // The back-edge targets the trigger rather than `a` on purpose: a loop closing
    // on `a` (trigger -> a -> b -> a) gives `a` two predecessors, so the engine
    // lowers its incoming edges as a fan-in merge barrier (waiting edges). That
    // barrier deadlocks the loop before it can iterate — the run then settles as
    // `Ok` with only the trigger having run, and the recursion limit is never
    // exercised. Closing the loop on the (single-predecessor) trigger keeps every
    // edge a plain edge, so the graph actually loops and the limit fires.
    // The cycle is pure control flow (output_parser passthroughs), so the stock
    // mock capabilities are fine — no slot needs swapping here.
    let caps = mock_capabilities();

    let graph = WorkflowGraph {
        name: "recursion_cycle".to_string(),
        nodes: vec![
            node("t", NodeKind::Trigger, json!({ "recursion_limit": 5 })),
            node("a", NodeKind::OutputParser, Value::Null),
            node("b", NodeKind::OutputParser, Value::Null),
        ],
        edges: vec![edge("t", "a"), edge("a", "b"), edge("b", "t")],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let guarded = tokio::time::timeout(Duration::from_secs(10), run(&compiled, json!({}), &caps));
    match guarded.await {
        Err(_elapsed) => panic!("run hung past 10s — the recursion limit did not bound the cycle"),
        Ok(inner) => assert!(
            inner.is_err(),
            "the recursion/step limit should error the cyclic run, got: {inner:?}"
        ),
    }
}

#![cfg(feature = "mock")]
//! End-to-end data-flow tests focused on **item pairing** and **multi-item
//! propagation** through the engine.
//!
//! These exercise the item-based currency that flows between nodes (see
//! `src/data.rs`): every element on a connection is an [`Item`] carrying a `json`
//! payload, an optional `binary` attachment, and an optional `paired_item` index
//! that best-effort correlates an output back to the input it derived from.
//!
//! The assertions below encode the *actual* pairing behavior of the current
//! executors, verified against their sources:
//!
//! * `split_out` (`src/nodes/control_flow/split_out.rs`) pairs every fanned-out
//!   element with the index of the **source input item** it came from. With a
//!   single trigger item (index 0), all fanned elements are therefore paired to
//!   `Some(0)` — the pairing is the *source* index, not the element's position.
//! * `transform` (`src/nodes/control_flow/transform.rs`) re-pairs each output to
//!   the **positional index of the item within its own input batch**, discarding
//!   any upstream `paired_item`. So a 3-item batch becomes paired `0, 1, 2`.
//! * `merge` and `output_parser` are identity passthroughs: they preserve each
//!   item (json + pairing) verbatim.
//!
//! Output layout, as produced by `engine::run`:
//! `outcome.output["nodes"]["<id>"]["items"][k]` — each item serializes its
//! `"json"` and, when set, its `"paired_item"` (the `binary` and `paired_item`
//! fields are skipped when `None`).
//!
//! Gated behind the `mock` feature, so `cargo test` (no features) skips this file
//! while `cargo test --all-features` runs it.

use serde_json::{Value, json};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config (no ports, no position).
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a manual trigger node.
fn trigger(id: &str) -> Node {
    node(
        id,
        NodeKind::Trigger,
        json!({ "kind": TriggerKind::Manual }),
    )
}

/// Builds an edge from `from_node`'s `from_port` into `to_node`'s `"main"` port.
fn edge(from_node: &str, from_port: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: from_port.to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

/// Borrows the serialized items array a node contributed to the run state.
fn items<'a>(out: &'a Value, node_id: &str) -> &'a Vec<Value> {
    out["nodes"][node_id]["items"]
        .as_array()
        .unwrap_or_else(|| panic!("node `{node_id}` should have produced an items array"))
}

/// Test 1 — `split_out` pairs each fanned element with its **source input index**.
///
/// A single trigger item (index 0) holding a 3-element array fans out into three
/// items, each paired to `Some(0)` — the index of the one input they all came
/// from, per `split_out.rs`'s `Item::new(element).paired_with(index)`.
#[tokio::test]
async fn split_out_sets_source_index_pairing() {
    let graph = WorkflowGraph {
        name: "split_pairing".to_string(),
        nodes: vec![
            trigger("start"),
            node("split", NodeKind::SplitOut, json!({ "path": "xs" })),
        ],
        edges: vec![edge("start", "main", "split")],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "xs": [ { "v": 1 }, { "v": 2 }, { "v": 3 } ] }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    let split = items(out, "split");
    assert_eq!(
        split.len(),
        3,
        "split_out fans the 3-element array into 3 items"
    );

    for (k, expected_v) in [1, 2, 3].into_iter().enumerate() {
        assert_eq!(split[k]["json"], json!({ "v": expected_v }));
        // Every element pairs to source input index 0 (there was one input item).
        assert_eq!(
            split[k]["paired_item"],
            json!(0),
            "split_out pairs every element to its source input index (0), not its own position",
        );
    }
}

/// Test 2 — pairing propagates through a `split_out -> transform -> merge` chain,
/// and the item count is conserved end to end.
///
/// * `split_out` produces 3 items paired `0, 0, 0` (all from source input 0).
/// * `transform` re-pairs to positional indices `0, 1, 2` while applying `set`
///   to each item (`transform.rs` uses `paired_with(index)` over its own batch).
/// * `merge` concatenates/passes through all 3, preserving json + pairing.
/// * The final item count equals the input array length (3).
#[tokio::test]
async fn pairing_propagates_through_split_transform_merge() {
    let graph = WorkflowGraph {
        name: "pairing_chain".to_string(),
        nodes: vec![
            trigger("start"),
            node("split", NodeKind::SplitOut, json!({ "path": "xs" })),
            node(
                "shape",
                NodeKind::Transform,
                json!({ "set": { "seen": true } }),
            ),
            node("collect", NodeKind::Merge, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "split"),
            edge("split", "main", "shape"),
            edge("shape", "main", "collect"),
        ],
        ..Default::default()
    };

    let input_len = 3;
    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "xs": [ { "v": 1 }, { "v": 2 }, { "v": 3 } ] }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    // Stage 1: split fans out to 3, all paired to source input 0.
    let split = items(out, "split");
    assert_eq!(split.len(), input_len);
    for item in split {
        assert_eq!(item["paired_item"], json!(0));
    }

    // Stage 2: transform preserves the count, applies `set` per item, and re-pairs
    // to its own positional indices 0, 1, 2 (discarding the upstream 0, 0, 0).
    let shape = items(out, "shape");
    assert_eq!(
        shape.len(),
        input_len,
        "transform is 1:1 over its input batch"
    );
    for (k, expected_v) in [1, 2, 3].into_iter().enumerate() {
        assert_eq!(
            shape[k]["json"]["v"],
            json!(expected_v),
            "original field kept"
        );
        assert_eq!(
            shape[k]["json"]["seen"],
            json!(true),
            "`set` applied per item"
        );
        assert_eq!(
            shape[k]["paired_item"],
            json!(k),
            "transform re-pairs each output to its positional input index",
        );
    }

    // Stage 3: merge concatenates all items, preserving json + pairing verbatim.
    let collect = items(out, "collect");
    assert_eq!(
        collect.len(),
        input_len,
        "merge concatenates all items; final count == input array length",
    );
    for (k, expected_v) in [1, 2, 3].into_iter().enumerate() {
        assert_eq!(collect[k]["json"]["v"], json!(expected_v));
        assert_eq!(collect[k]["json"]["seen"], json!(true));
        assert_eq!(
            collect[k]["paired_item"],
            json!(k),
            "merge preserves the pairing transform assigned",
        );
    }
}

/// Test 3 — a multi-item `transform` keeps per-item pairing and evaluates its
/// expression against each item independently.
///
/// Fanning `[{v:10},{v:20},{v:30}]` through `split_out` gives `transform` a
/// 3-item batch; `set.copy_v = =item.v` copies each item's own `v`, proving the
/// transform runs per item, and each output is paired to its positional index.
#[tokio::test]
async fn multi_item_transform_keeps_pairing_and_applies_per_item() {
    let graph = WorkflowGraph {
        name: "multi_item_transform".to_string(),
        nodes: vec![
            trigger("start"),
            node("split", NodeKind::SplitOut, json!({ "path": "xs" })),
            node(
                "shape",
                NodeKind::Transform,
                json!({ "set": { "copy_v": "=item.v" } }),
            ),
        ],
        edges: vec![
            edge("start", "main", "split"),
            edge("split", "main", "shape"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "xs": [ { "v": 10 }, { "v": 20 }, { "v": 30 } ] }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    let shape = items(out, "shape");
    assert_eq!(shape.len(), 3, "transform maps 1:1 over the 3 fanned items");
    for (k, expected_v) in [10, 20, 30].into_iter().enumerate() {
        // Per-item evaluation: each output's copy_v equals *that* item's v.
        assert_eq!(shape[k]["json"]["v"], json!(expected_v));
        assert_eq!(
            shape[k]["json"]["copy_v"],
            json!(expected_v),
            "the expression is evaluated against each item independently",
        );
        assert_eq!(
            shape[k]["paired_item"],
            json!(k),
            "each output keeps its positional pairing index",
        );
    }
}

// NOTE: `binary` is currently plumbed only at the `Item` level (`src/data.rs`) and
// is exercised solely at the serde layer — no executor or mock capability ever
// produces a non-null `binary` attachment (verified across `src/nodes/**` and
// `src/caps/mock.rs`). This test therefore documents that reality rather than
// inventing behavior: with a json-only seed, items flowing through the engine
// carry no `binary` field (it is `Option::None` and skipped from the wire form).
/// Test 4 — `binary` stays absent end to end when no node emits it.
///
/// Seeding a json-only trigger and flowing through `split_out` and the
/// identity-passthrough `output_parser`, every serialized item omits `binary`.
#[tokio::test]
async fn binary_field_absent_when_no_node_emits_it() {
    let graph = WorkflowGraph {
        name: "binary_absent".to_string(),
        nodes: vec![
            trigger("start"),
            node("split", NodeKind::SplitOut, json!({ "path": "xs" })),
            node("parse", NodeKind::OutputParser, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "split"),
            edge("split", "main", "parse"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "xs": [ { "v": 1 }, { "v": 2 } ] }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    for node_id in ["split", "parse"] {
        let stage = items(out, node_id);
        assert!(!stage.is_empty(), "node `{node_id}` produced items");
        for item in stage {
            // `binary` is skipped when `None`, so it is absent from the wire form.
            assert!(
                item.get("binary").is_none(),
                "no executor emits `binary`, so `{node_id}` items omit the field",
            );
        }
    }
}

#![cfg(feature = "mock")]
//! End-to-end integration tests for the tinyflows engine.
//!
//! Each test builds a realistic, multi-node [`WorkflowGraph`] inspired by the
//! project's reference workflows, compiles it, and runs
//! it against the deterministic [mock capabilities](tinyflows::caps::mock). The
//! goal is to prove the whole pipeline — model → validate → compile → run — works
//! for the constructs the engine currently supports: linear chains, `split_out`
//! fan-out, `condition`/`switch` branching, and nested `sub_workflow` execution.
//!
//! The mocks are deterministic echoes (see `src/caps/mock.rs`): `http` returns
//! `{status, request}`, `code` returns `{result: <input>}`, `tools.invoke` returns
//! `{tool, args}`, and `llm.complete` returns `{completion: <request>}`. Assertions
//! therefore check the *shape and presence* of each node's contributed items in the
//! run state (`output["nodes"]["<id>"]["items"]`) rather than brittle deep equality
//! over the echoed payloads.
//!
//! This file is gated behind the `mock` cargo feature, so `cargo test` (no
//! features) skips it while `cargo test --all-features` runs it.

use serde_json::{Value, json};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config (no ports, no position).
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a trigger node whose firing mode is carried in config as a [`TriggerKind`].
fn trigger(id: &str, kind: TriggerKind) -> Node {
    node(id, NodeKind::Trigger, json!({ "kind": kind }))
}

/// Builds an edge from `from_node`'s `from_port` into `to_node`'s `"main"` port.
fn edge(from_node: &str, from_port: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: from_port.to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

/// Reference workflow #4 (Customer insights) — a fully linear chain:
/// `trigger -> http_request (get reviews) -> code (cluster) -> split_out ->
/// agent -> tool_call (append to sheet)`. Proves a five-hop pipeline mixing every
/// integration node compiles and drives to completion, with data flowing through.
#[tokio::test]
async fn customer_insights_linear() {
    let graph = WorkflowGraph {
        name: "customer_insights".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node(
                "reviews",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://qdrant.example/reviews" }),
            ),
            node(
                "cluster",
                NodeKind::Code,
                json!({ "language": "python", "source": "kmeans(input)" }),
            ),
            // The code node wraps its input under `result` (an array), so splitting
            // on that path fans the clusters back out into individual items.
            node("split", NodeKind::SplitOut, json!({ "path": "result" })),
            node(
                "insights",
                NodeKind::Agent,
                json!({ "prompt": "Summarise customer sentiment", "model": "openai" }),
            ),
            node(
                "sheet",
                NodeKind::ToolCall,
                json!({ "slug": "googlesheets.append", "args": { "sheet": "reviews" } }),
            ),
        ],
        edges: vec![
            edge("start", "main", "reviews"),
            edge("reviews", "main", "cluster"),
            edge("cluster", "main", "split"),
            edge("split", "main", "insights"),
            edge("insights", "main", "sheet"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "query": "recent reviews" }),
        &mock_capabilities(),
    )
    .await
    .expect("run");
    let out = &outcome.output;

    // The trigger payload is preserved in the run metadata.
    assert_eq!(out["run"]["trigger"], json!({ "query": "recent reviews" }));

    // The HTTP node returned the canned 200 echo of its request descriptor.
    assert_eq!(out["nodes"]["reviews"]["items"][0]["json"]["status"], 200);
    assert_eq!(
        out["nodes"]["reviews"]["items"][0]["json"]["request"]["url"],
        "https://qdrant.example/reviews"
    );

    // split_out fanned the code node's `result` array back out into >=1 item.
    let split_items = out["nodes"]["split"]["items"]
        .as_array()
        .expect("split_out produced an items array");
    assert!(
        !split_items.is_empty(),
        "split_out should emit at least one item"
    );

    // The terminal tool_call ran and echoed the slug it was invoked with.
    assert_eq!(
        out["nodes"]["sheet"]["items"][0]["json"]["tool"],
        "googlesheets.append"
    );
    assert_eq!(
        out["nodes"]["sheet"]["items"][0]["json"]["args"]["sheet"],
        "reviews"
    );
}

/// Reference workflow #3 (API router) — a `switch` multi-way branch:
/// `trigger (webhook) -> agent -> transform (set type) -> switch -> {get | post}`.
/// A `transform` seeds a deterministic `type` field so the switch's `=item.type`
/// key is stable; only the matching `get` branch must run.
#[tokio::test]
async fn api_router_switch() {
    let graph = WorkflowGraph {
        name: "api_router".to_string(),
        nodes: vec![
            trigger("hook", TriggerKind::Webhook),
            node(
                "router",
                NodeKind::Agent,
                json!({ "prompt": "Classify the request", "model": "gemini" }),
            ),
            // Force a deterministic switch key onto the agent's output item.
            node(
                "label",
                NodeKind::Transform,
                json!({ "set": { "type": "get" } }),
            ),
            node(
                "switch",
                NodeKind::Switch,
                json!({ "expression": "=item.type" }),
            ),
            node(
                "http_get",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://api.example/props" }),
            ),
            node(
                "http_post",
                NodeKind::HttpRequest,
                json!({ "method": "POST", "url": "https://api.example/create" }),
            ),
        ],
        edges: vec![
            edge("hook", "main", "router"),
            edge("router", "main", "label"),
            edge("label", "main", "switch"),
            edge("switch", "get", "http_get"),
            edge("switch", "post", "http_post"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({ "method": "GET" }), &mock_capabilities())
        .await
        .expect("run");
    let out = &outcome.output;

    // Only the `get` branch was taken.
    assert!(
        !out["nodes"]["http_get"]["items"].is_null(),
        "the `get` branch should have run"
    );
    assert_eq!(out["nodes"]["http_get"]["items"][0]["json"]["status"], 200);
    assert_eq!(
        out["nodes"]["http_get"]["items"][0]["json"]["request"]["url"],
        "https://api.example/props"
    );
    // The `post` branch node never executed, so it has no slot in the run state.
    assert!(
        out["nodes"]["http_post"].is_null(),
        "the `post` branch should not have run"
    );
}

/// Reference workflow #1 (Create-user onboarding) — an IF branch:
/// `trigger (form) -> transform (set is_manager) -> condition -> {true | false}`.
/// A `transform` sets a boolean literal so the `condition`'s truthiness check is
/// deterministic; only the `true` branch's tool_call must run.
#[tokio::test]
async fn onboarding_condition() {
    let graph = WorkflowGraph {
        name: "onboarding".to_string(),
        nodes: vec![
            trigger("form", TriggerKind::Form),
            node(
                "flag",
                NodeKind::Transform,
                json!({ "set": { "is_manager": true } }),
            ),
            node(
                "is_manager",
                NodeKind::Condition,
                json!({ "field": "is_manager" }),
            ),
            node(
                "add_to_channel",
                NodeKind::ToolCall,
                json!({ "slug": "slack.add_to_channel", "args": { "channel": "managers" } }),
            ),
            node(
                "update_profile",
                NodeKind::ToolCall,
                json!({ "slug": "slack.update_profile", "args": {} }),
            ),
        ],
        edges: vec![
            edge("form", "main", "flag"),
            edge("flag", "main", "is_manager"),
            edge("is_manager", "true", "add_to_channel"),
            edge("is_manager", "false", "update_profile"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
