/// A nested `sub_workflow`: a parent `trigger -> sub_workflow` embeds a child
/// `trigger -> output_parser` graph. The sub_workflow node compiles and runs the
/// child via the same engine and emits the child's final run state as its item, so
/// the parent's sub_workflow slot must contain the child's `run` + `nodes` state.
#[tokio::test]
async fn nested_sub_workflow() {
    let child = WorkflowGraph {
        name: "child".to_string(),
        nodes: vec![
            trigger("child_trigger", TriggerKind::ExecuteByWorkflow),
            node("parse", NodeKind::OutputParser, Value::Null),
        ],
        edges: vec![edge("child_trigger", "main", "parse")],
        ..Default::default()
    };
    let child_value = serde_json::to_value(&child).expect("serialize child graph");

    let parent = WorkflowGraph {
        name: "parent".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node(
                "child",
                NodeKind::SubWorkflow,
                json!({ "workflow": child_value }),
            ),
        ],
        edges: vec![edge("start", "main", "child")],
        ..Default::default()
    };

    let compiled = compile(&parent).expect("compile parent");
    let outcome = run(&compiled, json!({ "payload": 42 }), &mock_capabilities())
        .await
        .expect("run parent");
    let out = &outcome.output;

    // The sub_workflow emitted the child's final run state as a single item.
    let child_state = &out["nodes"]["child"]["items"][0]["json"];
    assert!(
        !child_state["run"]["trigger"].is_null(),
        "child run state should carry its trigger payload"
    );
    // The child actually ran end-to-end: its output_parser node produced items.
    assert!(
        !child_state["nodes"]["parse"]["items"].is_null(),
        "the child's output_parser node should have run"
    );
}

#![cfg(feature = "mock")]
//! End-to-end integration tests for parallel fan-out and the `merge` fan-in.
//!
//! When a node has more than one outgoing edge that all share a single output
//! port, the engine treats it as a **parallel fan-out**: every successor runs
//! concurrently in the same superstep. A `merge` node with multiple predecessors
//! is lowered with waiting edges, so it runs only once *every* predecessor has
//! finished (the merge barrier) and its input is the concatenation of all
//! predecessors' items.
//!
//! These tests assert (a) a 3-way fan-out joined by a merge yields 3 items at the
//! merge, and (b) in a diamond each branch contributes its own distinctly-marked
//! item to the merge.
//!
//! Gated behind the `mock` cargo feature.

use serde_json::{Value, json};
use std::collections::HashSet;
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config (no ports, no position).
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a manual trigger node.
fn trigger(id: &str) -> Node {
    node(
        id,
        NodeKind::Trigger,
        json!({ "kind": TriggerKind::Manual }),
    )
}

/// Builds an edge from `from_node`'s `from_port` into `to_node`'s `"main"` port.
fn edge(from_node: &str, from_port: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: from_port.to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

#[tokio::test]
async fn fan_out_to_three_successors_joins_at_merge() {
    // trigger fans out (three `main`-port edges) to three independent http nodes,
    // each producing exactly one item; a merge concatenates all three.
    let graph = WorkflowGraph {
        name: "fan_out_merge".to_string(),
        nodes: vec![
            trigger("start"),
            node(
                "a",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://svc/a" }),
            ),
            node(
                "b",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://svc/b" }),
            ),
            node(
                "c",
                NodeKind::HttpRequest,
                json!({ "method": "GET", "url": "https://svc/c" }),
            ),
            node("join", NodeKind::Merge, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "a"),
            edge("start", "main", "b"),
            edge("start", "main", "c"),
            edge("a", "main", "join"),
            edge("b", "main", "join"),
            edge("c", "main", "join"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({ "seed": 1 }), &mock_capabilities())
        .await
        .expect("run");
    let out = &outcome.output;

    // All three concurrent successors ran.
    for id in ["a", "b", "c"] {
        assert_eq!(
            out["nodes"][id]["items"][0]["json"]["status"], 200,
            "fan-out branch {id} should have executed"
        );
    }

    // The merge barrier waited for all three, then concatenated their items.
    let merged = out["nodes"]["join"]["items"]
        .as_array()
        .expect("merge produced an items array");
    assert_eq!(
        merged.len(),
        3,
        "merge should combine one item from each of the three predecessors"
    );

    // The three merged items are the three distinct upstream URLs.
    let urls: HashSet<String> = merged
        .iter()
        .map(|item| item["json"]["request"]["url"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        urls,
        HashSet::from([
            "https://svc/a".to_string(),
            "https://svc/b".to_string(),
            "https://svc/c".to_string(),
        ])
    );
}

#[tokio::test]
async fn diamond_every_branch_contributes_to_merge() {
    // A diamond with a non-trigger apex: trigger -> apex(code) fans out to three
    // transforms, each stamping a distinct `branch` marker, then a merge joins
    // them. Every branch must contribute exactly one item to the merge.
    let graph = WorkflowGraph {
        name: "diamond".to_string(),
        nodes: vec![
            trigger("start"),
            node(
                "apex",
                NodeKind::Code,
                json!({ "language": "python", "source": "passthrough(input)" }),
            ),
            node(
                "branch_a",
                NodeKind::Transform,
                json!({ "set": { "branch": "a" } }),
            ),
            node(
                "branch_b",
                NodeKind::Transform,
                json!({ "set": { "branch": "b" } }),
            ),
            node(
                "branch_c",
                NodeKind::Transform,
                json!({ "set": { "branch": "c" } }),
            ),
            node("join", NodeKind::Merge, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "apex"),
            edge("apex", "main", "branch_a"),
            edge("apex", "main", "branch_b"),
            edge("apex", "main", "branch_c"),
            edge("branch_a", "main", "join"),
            edge("branch_b", "main", "join"),
            edge("branch_c", "main", "join"),
        ],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({ "seed": 7 }), &mock_capabilities())
        .await
        .expect("run");
    let out = &outcome.output;

    let merged = out["nodes"]["join"]["items"]
        .as_array()
        .expect("merge produced an items array");
    assert_eq!(
        merged.len(),
        3,
        "each of the three branches contributes one item"
    );

    // Every branch's distinct marker is present exactly once.
    let branches: HashSet<String> = merged
        .iter()
        .map(|item| item["json"]["branch"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        branches,
        HashSet::from(["a".to_string(), "b".to_string(), "c".to_string()]),
        "all three branches must be represented in the merge"
    );

    // Each merged item still carries the apex code node's `result` payload,
    // proving data flowed apex -> branch -> merge.
    for item in merged {
        assert!(
            !item["json"]["result"].is_null(),
            "merged item should retain the apex code node's result"
        );
    }
}

#![cfg(feature = "mock")]
//! End-to-end tests for jaq/jq expression evaluation inside running workflows.
//!
//! Config strings prefixed with `=` are expressions (see `src/expr.rs`): a simple
//! dotted path resolves by segment-walk, anything else runs as a jq program over
//! the evaluation scope `{ item, run }`. These tests exercise expressions in the
//! nodes that consume them — `transform` (its `set` map), `switch` (its case key),
//! and a `condition` fed by a computed field — plus a `split_out` → `transform`
//! combo, and assert the *computed values* land in the run output.
//!
//! Gated behind the `mock` feature, so plain `cargo test` skips it while
//! `cargo test --all-features` runs it.

use serde_json::{Value, json};
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

/// Builds a node with the given id, kind, and config.
fn node(id: &str, kind: NodeKind, config: Value) -> Node {
    Node {
        id: id.to_string(),
        kind,
        type_version: 1,
        name: id.to_string(),
        config,
        ports: vec![],
        position: None,
    }
}

/// Builds a trigger node with the given firing mode.
fn trigger(id: &str, kind: TriggerKind) -> Node {
    node(id, NodeKind::Trigger, json!({ "kind": kind }))
}

/// Builds an edge from `from_node`'s `from_port` into `to_node`'s `main` port.
fn edge(from_node: &str, from_port: &str, to_node: &str) -> Edge {
    Edge {
        from_node: from_node.to_string(),
        from_port: from_port.to_string(),
        to_node: to_node.to_string(),
        to_port: "main".to_string(),
    }
}

/// A `transform` whose `set` map uses jq programs — `add`, `length`, `map`, and
/// array indexing — over the incoming item. Each computed field must appear on
/// the emitted item with the right value.
#[tokio::test]
async fn transform_evaluates_jq_aggregations() {
    let graph = WorkflowGraph {
        name: "jq_transform".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node(
                "compute",
                NodeKind::Transform,
                json!({
                    "set": {
                        "total": "=.item.nums | add",
                        "count": "=.item.nums | length",
                        "doubled": "=.item.nums | map(. * 2)",
                        "first": "=.item.nums[0]"
                    }
                }),
            ),
        ],
        edges: vec![edge("start", "main", "compute")],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "nums": [1, 2, 3, 4] }),
        &mock_capabilities(),
    )
    .await
    .expect("run");

    let item = &outcome.output["nodes"]["compute"]["items"][0]["json"];
    assert_eq!(item["total"], json!(10), "add should sum the array");
    assert_eq!(item["count"], json!(4), "length should count the elements");
    assert_eq!(
        item["doubled"],
        json!([2, 4, 6, 8]),
        "map(. * 2) should double each element"
    );
    assert_eq!(item["first"], json!(1), "index [0] should take the first");
    // The source field is preserved alongside the computed ones.
    assert_eq!(item["nums"], json!([1, 2, 3, 4]));
}

/// A `switch` whose case key is a jq program computing a discriminant string.
/// Only the branch matching the computed port must run.
#[tokio::test]
async fn switch_routes_on_jq_discriminant() {
    let graph = WorkflowGraph {
        name: "jq_switch".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            // priority > 5 => "high", otherwise "low" — a jq-computed case key.
            node(
                "route",
                NodeKind::Switch,
                json!({ "expression": "=if .item.priority > 5 then \"high\" else \"low\" end" }),
            ),
            node("high", NodeKind::OutputParser, Value::Null),
            node("low", NodeKind::OutputParser, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "route"),
            edge("route", "high", "high"),
            edge("route", "low", "low"),
        ],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({ "priority": 9 }), &mock_capabilities())
        .await
        .expect("run");

    assert!(
        !outcome.output["nodes"]["high"]["items"].is_null(),
        "priority 9 should route to the `high` branch"
    );
    assert!(
        outcome.output["nodes"]["low"].is_null(),
        "the `low` branch should not have run"
    );
}

