/// A `condition` driven by a field that a preceding `transform` computed with a
/// jq comparison. The boolean result selects the `true`/`false` port.
#[tokio::test]
async fn condition_driven_by_computed_field() {
    let graph = WorkflowGraph {
        name: "computed_condition".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            // Compute a boolean `passed` field via a jq comparison expression.
            node(
                "grade",
                NodeKind::Transform,
                json!({ "set": { "passed": "=.item.score >= 50" } }),
            ),
            node("check", NodeKind::Condition, json!({ "field": "passed" })),
            node("accepted", NodeKind::OutputParser, Value::Null),
            node("rejected", NodeKind::OutputParser, Value::Null),
        ],
        edges: vec![
            edge("start", "main", "grade"),
            edge("grade", "main", "check"),
            edge("check", "true", "accepted"),
            edge("check", "false", "rejected"),
        ],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let outcome = run(&compiled, json!({ "score": 73 }), &mock_capabilities())
        .await
        .expect("run");

    // The transform actually computed the boolean.
    assert_eq!(
        outcome.output["nodes"]["grade"]["items"][0]["json"]["passed"],
        json!(true),
        "score 73 >= 50 should compute `passed = true`"
    );
    assert!(
        !outcome.output["nodes"]["accepted"]["items"].is_null(),
        "a passing score should route to the `true` branch"
    );
    assert!(
        outcome.output["nodes"]["rejected"].is_null(),
        "the `false` branch should not have run"
    );
}

/// A `split_out` → `transform` combo: fan an array into one item per element,
/// then compute a field per item with a jq expression. Every emitted item must
/// carry the per-element computed value.
#[tokio::test]
async fn split_out_then_transform_computes_per_item() {
    let graph = WorkflowGraph {
        name: "split_transform".to_string(),
        nodes: vec![
            trigger("start", TriggerKind::Manual),
            node("fan", NodeKind::SplitOut, json!({ "path": "orders" })),
            // Each fanned item is one order object; compute a `total` per item.
            node(
                "price",
                NodeKind::Transform,
                json!({ "set": { "total": "=.item.qty * .item.unit" } }),
            ),
        ],
        edges: vec![edge("start", "main", "fan"), edge("fan", "main", "price")],
        ..Default::default()
    };
    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({
            "orders": [
                { "qty": 2, "unit": 5 },
                { "qty": 3, "unit": 10 }
            ]
        }),
        &mock_capabilities(),
    )
    .await
    .expect("run");

    // split_out fanned the two orders into two items.
    let items = outcome.output["nodes"]["price"]["items"]
        .as_array()
        .expect("transform produced an items array");
    assert_eq!(items.len(), 2, "two orders should fan out into two items");
    assert_eq!(
        items[0]["json"]["total"],
        json!(10),
        "first order total should be 2 * 5"
    );
    assert_eq!(
        items[1]["json"]["total"],
        json!(30),
        "second order total should be 3 * 10"
    );
}

#![cfg(feature = "mock")]
//! End-to-end test for **inline data-binding** into integration-node config.
//!
//! Capability-backed nodes (`agent`, `tool_call`, `http_request`) resolve any
//! `=`-expressions embedded in their config against the node's input before the
//! config reaches the host capability (see `src/expr.rs`'s `resolve` and
//! `src/nodes/mod.rs`'s `expr_scope`, which builds `{ item, items, run }`).
//!
//! Here a manual trigger feeds `{ name, channel }` into a `tool_call` whose
//! `args` reference `=item.channel` and `=item.name`. The mock `ToolInvoker`
//! echoes the args it was invoked with, so the run output proves the upstream
//! trigger data flowed into the resolved tool arguments end-to-end.
//!
//! Gated behind the `mock` feature, so `cargo test` (no features) skips this file
//! while `cargo test --all-features` runs it.

use serde_json::json;
use tinyflows::caps::mock::mock_capabilities;
use tinyflows::compiler::compile;
use tinyflows::engine::run;
use tinyflows::model::{Edge, Node, NodeKind, TriggerKind, WorkflowGraph};

#[tokio::test]
async fn tool_call_args_bind_to_upstream_trigger_data() {
    let graph = WorkflowGraph {
        name: "data_binding".to_string(),
        nodes: vec![
            Node {
                id: "trigger".into(),
                kind: NodeKind::Trigger,
                type_version: 1,
                name: "trigger".into(),
                config: json!({ "kind": TriggerKind::Manual }),
                ports: vec![],
                position: None,
            },
            Node {
                id: "post".into(),
                kind: NodeKind::ToolCall,
                type_version: 1,
                name: "post".into(),
                config: json!({
                    "slug": "slack.send",
                    "args": { "channel": "=item.channel", "text": "=item.name" },
                }),
                ports: vec![],
                position: None,
            },
        ],
        edges: vec![Edge {
            from_node: "trigger".into(),
            from_port: "main".into(),
            to_node: "post".into(),
            to_port: "main".into(),
        }],
        ..Default::default()
    };

    let compiled = compile(&graph).expect("compile");
    let outcome = run(
        &compiled,
        json!({ "name": "Ada", "channel": "#ops" }),
        &mock_capabilities(),
    )
    .await
    .expect("run should complete");

    // The `=item.*` expressions resolved against the trigger payload before the
    // mock tool echoed the args back — proving inline data-binding end-to-end.
    assert_eq!(
        outcome.output["nodes"]["post"]["items"][0]["json"]["args"],
        json!({ "channel": "#ops", "text": "Ada" })
    );
}

//! In-memory mock capability implementations for tests and examples.
//!
//! Enabled inside this crate's own tests automatically, or downstream via the
//! `mock` cargo feature. The mocks are deterministic echoes — enough to exercise
//! the engine and the reference workflows without any external services.

use std::sync::Arc;

use async_trait::async_trait;
use serde_json::{Value, json};

use crate::caps::{
    Capabilities, CodeLanguage, CodeRunner, HttpClient, LlmProvider, StateStore, ToolInvoker,
};
use crate::error::Result;

/// An [`LlmProvider`] that echoes the request back under a `completion` key.
#[derive(Debug, Default, Clone)]
pub struct MockLlm;

#[async_trait]
impl LlmProvider for MockLlm {
    async fn complete(&self, request: Value, conn: Option<&str>) -> Result<Value> {
        Ok(json!({ "completion": request, "connection": conn }))
    }
}

/// A [`ToolInvoker`] that echoes the slug and args it was called with.
#[derive(Debug, Default, Clone)]
pub struct MockTools;

#[async_trait]
impl ToolInvoker for MockTools {
    async fn invoke(&self, slug: &str, args: Value, conn: Option<&str>) -> Result<Value> {
        Ok(json!({ "tool": slug, "args": args, "connection": conn }))
    }
}

/// An [`HttpClient`] that returns a canned `200` response echoing the request.
#[derive(Debug, Default, Clone)]
pub struct MockHttp;

#[async_trait]
impl HttpClient for MockHttp {
    async fn request(&self, request: Value, conn: Option<&str>) -> Result<Value> {
        Ok(json!({ "status": 200, "request": request, "connection": conn }))
    }
}

/// A [`CodeRunner`] that returns its input unchanged under a `result` key.
#[derive(Debug, Default, Clone)]
pub struct MockCode;

#[async_trait]
impl CodeRunner for MockCode {
    async fn run(&self, _language: CodeLanguage, _source: &str, input: Value) -> Result<Value> {
        Ok(json!({ "result": input }))
    }
}

/// A [`StateStore`] backed by an in-memory map guarded by a mutex.
#[derive(Debug, Default)]
pub struct MockStateStore {
    inner: std::sync::Mutex<std::collections::HashMap<String, Value>>,
}

#[async_trait]
impl StateStore for MockStateStore {
    async fn load(&self, key: &str) -> Result<Option<Value>> {
        Ok(self.inner.lock().expect("lock").get(key).cloned())
    }

    async fn store(&self, key: &str, value: Value) -> Result<()> {
        self.inner
            .lock()
            .expect("lock")
            .insert(key.to_string(), value);
        Ok(())
    }
}

/// Builds a [`Capabilities`] bundle wired entirely to the mock implementations.
#[must_use]
pub fn mock_capabilities() -> Capabilities {
    Capabilities {
        llm: Arc::new(MockLlm),
        tools: Arc::new(MockTools),
        http: Arc::new(MockHttp),
        code: Arc::new(MockCode),
        state: Arc::new(MockStateStore::default()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn mock_tools_echo() {
        let caps = mock_capabilities();
        let out = caps
            .tools
            .invoke("slack.post", json!({"x": 1}), None)
            .await
            .unwrap();
        assert_eq!(out["tool"], "slack.post");
    }

    #[tokio::test]
    async fn mock_llm_echoes_request_and_threads_connection() {
        let llm = MockLlm;
        let with_conn = llm
            .complete(json!({"prompt": "hi"}), Some("conn_1"))
            .await
            .unwrap();
        assert_eq!(with_conn["completion"], json!({"prompt": "hi"}));
        assert_eq!(with_conn["connection"], "conn_1");

        let without_conn = llm.complete(json!({"prompt": "hi"}), None).await.unwrap();
        assert!(without_conn["connection"].is_null());
    }

    #[tokio::test]
    async fn mock_tools_echoes_slug_args_and_connection() {
        let tools = MockTools;
        let with_conn = tools
            .invoke("gmail.send", json!({"to": "a@b.c"}), Some("conn_2"))
            .await
            .unwrap();
        assert_eq!(with_conn["tool"], "gmail.send");
        assert_eq!(with_conn["args"], json!({"to": "a@b.c"}));
        assert_eq!(with_conn["connection"], "conn_2");

        let without_conn = tools.invoke("gmail.send", json!({}), None).await.unwrap();
        assert!(without_conn["connection"].is_null());
    }

    #[tokio::test]
    async fn mock_http_returns_canned_200_and_threads_connection() {
        let http = MockHttp;
        let with_conn = http
            .request(json!({"method": "GET", "url": "https://x"}), Some("conn_3"))
            .await
            .unwrap();
        assert_eq!(with_conn["status"], 200);
        assert_eq!(with_conn["request"]["method"], "GET");
        assert_eq!(with_conn["connection"], "conn_3");

        let without_conn = http.request(json!({"method": "GET"}), None).await.unwrap();
        assert_eq!(without_conn["status"], 200);
        assert!(without_conn["connection"].is_null());
    }

    #[tokio::test]
    async fn mock_code_returns_input_under_result_key() {
        let code = MockCode;
        let js = code
            .run(CodeLanguage::JavaScript, "return 1;", json!({"n": 7}))
            .await
            .unwrap();
        assert_eq!(js["result"], json!({"n": 7}));

        // The language and source are ignored by the echo runner.
        let py = code
            .run(CodeLanguage::Python, "print(1)", json!([1, 2, 3]))
            .await
            .unwrap();
        assert_eq!(py["result"], json!([1, 2, 3]));
    }

    #[tokio::test]
    async fn mock_state_store_round_trips_and_misses() {
        let store = MockStateStore::default();
        assert!(store.load("missing").await.unwrap().is_none());

        store.store("k", json!({"v": 1})).await.unwrap();
        assert_eq!(store.load("k").await.unwrap(), Some(json!({"v": 1})));

        // Storing again overwrites the previous value.
        store.store("k", json!(2)).await.unwrap();
        assert_eq!(store.load("k").await.unwrap(), Some(json!(2)));
    }

    #[tokio::test]
    async fn mock_capabilities_state_store_round_trips_through_bundle() {
        let caps = mock_capabilities();
        // A missing key reads back as `None`.
        assert!(caps.state.load("k").await.unwrap().is_none());

        // A stored value is readable through the same bundle handle.
        caps.state.store("k", json!({"v": 1})).await.unwrap();
        assert_eq!(caps.state.load("k").await.unwrap(), Some(json!({"v": 1})));
    }

    #[tokio::test]
    async fn mock_capabilities_wires_every_slot() {
        let caps = mock_capabilities();
        assert_eq!(
            caps.llm.complete(json!({"p": 1}), None).await.unwrap()["completion"],
            json!({"p": 1})
        );
        assert_eq!(
            caps.tools.invoke("s", json!({}), None).await.unwrap()["tool"],
            "s"
        );
        assert_eq!(
            caps.http.request(json!({}), None).await.unwrap()["status"],
            200
        );
        assert_eq!(
            caps.code
                .run(CodeLanguage::Python, "", json!("x"))
                .await
                .unwrap()["result"],
            "x"
        );
    }
}

